var e={kind:`board`,caption:`5 个线程往同一个 new ConcurrentHashMap<>(4) 里 put（数组长度 8）`,stepTitles:{1:`JDK 8：空桶 CAS`,2:`遇到扩容先帮忙`,3:`锁住桶的头节点`,4:`计数并按需扩容`},cols:3,regions:[{id:`table`,label:`table 数组（只列出非空的桶）`},{id:`threads`,label:`线程`},{id:`ctl`,label:`控制字段`}],legend:[[`new`,`刚放入`],[`hit`,`正在处理 / 加锁`],[`ok`,`完成`],[`bad`,`CAS 失败`],[`dim`,`已迁走`]],frames:[{step:1,boxes:{table:{items:[{t:`还没有数组`}]},threads:{items:[{t:`线程A：put(banana)`,st:`hit`}],hot:!0},ctl:{items:[{t:`table = null`},{t:`sizeCtl = 0`}]}},calc:[[`表还没建`,`线程A 用 CAS 把 sizeCtl 改成 −1，抢到初始化权`],[`建表`,`长度 8，sizeCtl = 8 × 0.75 = 6`]],note:`new ConcurrentHashMap<>(4) 之后数组还没建。线程A 第一个 put，发现 table 为空：用 CAS 把 sizeCtl 改成 −1 抢初始化权（别的线程看到 −1 就让出 CPU 等着），建一个长度 8 的数组，sizeCtl 改成扩容阈值 6。`},{step:1,boxes:{table:{items:[{t:`[0] banana`,st:`new`}],hot:!0},threads:{items:[{t:`线程A：put(banana) 完成`,st:`ok`}]},ctl:{items:[{t:`数组长度 8`},{t:`sizeCtl = 6`},{t:`元素个数 1`}]}},calc:[[`spread("banana".hashCode()) & (8 − 1)`,`0 号桶`],[`桶是空的`,`CAS(null → banana) 成功，不加锁`]],note:`banana 算出来落在 0 号桶。桶是空的，直接用 CAS 把新节点放进去 —— 不加锁。`},{step:1,boxes:{table:{items:[{t:`[0] banana`,st:null},{t:`[1] 空`,st:`hit`}],hot:!0},threads:{items:[{t:`线程B：put(apple)`,st:`hit`},{t:`线程C：put(cherry)`,st:`hit`}],hot:!0},ctl:{items:[{t:`数组长度 8`},{t:`sizeCtl = 6`},{t:`元素个数 1`}]}},calc:[[`spread("apple".hashCode()) & (8 − 1)`,`1 号桶`],[`spread("cherry".hashCode()) & (8 − 1)`,`1 号桶`],[`两个线程同时看到`,`1 号桶是空的，都去 CAS`]],note:`线程B put(apple)、线程C put(cherry) 同时进来，两个 key 恰好都落在 1 号桶，两个线程都看到桶是空的，都准备 CAS 放节点。`},{step:1,boxes:{table:{items:[{t:`[0] banana`,st:null},{t:`[1] apple`,st:`new`}],hot:!0},threads:{items:[{t:`线程B：CAS 成功`,st:`ok`},{t:`线程C：CAS 失败，重试`,st:`bad`}],hot:!0},ctl:{items:[{t:`数组长度 8`},{t:`sizeCtl = 6`},{t:`元素个数 2`}]}},calc:[[`线程B`,`CAS(null → apple) 成功`],[`线程C`,`CAS(null → cherry) 失败：桶里已经是 apple 了`],[`线程C 回到循环`,`重新读这个桶`]],note:`CAS 只有一个能成功：线程B 先改成功，apple 放进去了；线程C 的 CAS 期望桶还是 null，实际已经不是，失败 —— 不阻塞，回到循环开头重新读这个桶。（谁先成功由调度决定，这里假设是 B。）`},{step:3,boxes:{table:{items:[{t:`[0] banana`,st:null},{t:`[1] apple → cherry`,st:`hit`}],hot:!0},threads:{items:[{t:`线程C：synchronized(apple)`,st:`hit`}],hot:!0},ctl:{items:[{t:`数组长度 8`},{t:`sizeCtl = 6`},{t:`元素个数 3`}]}},calc:[[`重试时`,`1 号桶非空，头节点是 apple`],[`加锁`,`synchronized 锁住头节点 apple（只锁这一个桶）`],[`链表里没有 cherry`,`追加到尾部：apple → cherry`]],note:`线程C 重试时 1 号桶已经有节点了：用 synchronized 锁住头节点 apple，确认头节点没被换掉后，沿链表找 —— 没有 cherry，追加到尾部。`},{step:3,boxes:{table:{items:[{t:`[0] banana → peach`,st:`hit`},{t:`[1] apple → cherry`,st:null},{t:`[3] grape`,st:`new`}],hot:!0},threads:{items:[{t:`线程A：synchronized(banana)`,st:`hit`},{t:`线程D：CAS 放 grape`,st:`ok`}],hot:!0},ctl:{items:[{t:`数组长度 8`},{t:`sizeCtl = 6`},{t:`元素个数 5`}]}},calc:[[`spread("peach".hashCode()) & (8 − 1)`,`0 号桶`],[`线程A`,`0 号桶非空 → 锁住头节点 banana，追加 peach`],[`spread("grape".hashCode()) & (8 − 1)`,`3 号桶`],[`线程D`,`3 号桶是空的 → CAS 放入，完全不受线程A 的锁影响`]],note:`线程A put(peach) 落在 0 号桶，锁住头节点 banana 往后追加；同一时刻线程D put(grape) 落在 3 号桶，直接 CAS 放入 —— 锁只锁一个桶，不同桶的写互不影响。`},{step:4,boxes:{table:{items:[{t:`[0] banana → peach`,st:null},{t:`[1] apple → cherry`,st:null},{t:`[3] grape`,st:null},{t:`[7] mango`,st:`new`}],hot:!0},threads:{items:[{t:`线程D：put(mango)`,st:`hit`}],hot:!0},ctl:{items:[{t:`数组长度 8`},{t:`sizeCtl = 6`},{t:`元素个数 6`},{t:`6 ≥ sizeCtl 6 → 扩容`,st:`hit`}],hot:!0}},calc:[[`spread("mango".hashCode()) & (8 − 1)`,`7 号桶`],[`addCount`,`元素个数 +1：先 CAS 改 baseCount，竞争激烈时分散到 CounterCell`],[`比较`,`元素个数 6 ≥ sizeCtl 6 → 扩容`]],note:`线程D 再 put(mango)，CAS 放进 7 号桶后调用 addCount 把个数加 1：变成 6，达到 sizeCtl（6），开始扩容。注意这里是「≥」就扩，和 HashMap 的「>」不一样。`},{step:2,boxes:{table:{items:[{t:`[0] 已迁走 → ForwardingNode`,st:`dim`},{t:`[1] 已迁走 → ForwardingNode`,st:`dim`},{t:`[3] 已迁走 → ForwardingNode`,st:`dim`},{t:`[7] 已迁走 → ForwardingNode`,st:`dim`},{t:`[2] 空 → ForwardingNode`,st:`hit`}],hot:!0},threads:{items:[{t:`线程D：迁移中（transfer）`,st:`hit`},{t:`线程E：put(lemon)`,st:`hit`}],hot:!0},ctl:{items:[{t:`数组长度 8`},{t:`sizeCtl = -2`},{t:`元素个数 6`},{t:`新数组长度 16`,st:`new`}]}},calc:[[`线程E 算出`,`lemon 在旧表的 2 号桶`],[`头节点 hash`,`MOVED（−1），是 ForwardingNode`],[`线程E`,`先 helpTransfer 帮忙迁移，迁完再在新表上 put`]],note:`扩容时线程D 从高位往低位逐个迁移桶，每迁完一个桶就在旧桶放一个 ForwardingNode（hash = MOVED = −1）。线程E 这时来 put(lemon)，看到桶头是 ForwardingNode，就先去帮忙迁移；整张表迁完后再到新表上重新 put。sizeCtl 在扩容期间是负数。`},{step:4,boxes:{table:{items:[{t:`[0] banana`,st:`ok`},{t:`[1] apple → cherry`,st:null},{t:`[2] lemon`,st:`new`},{t:`[8] peach`,st:`ok`},{t:`[11] grape`,st:null},{t:`[15] mango`,st:null}],hot:!0},threads:{items:[{t:`线程E：put(lemon) 完成`,st:`ok`}]},ctl:{items:[{t:`数组长度 16`},{t:`sizeCtl = 12`},{t:`元素个数 7`}]}},calc:[[`扩容后`,`长度 16，sizeCtl = 16 × 0.75 = 12`],[`0 号桶`,`banana、peach 按 hash & 8 拆开：banana 留在 0，peach 搬到 0 + 8 = 8`],[`lemon`,`新表 2 号桶，CAS 放入`]],note:`迁移完成：容量翻倍成 16，每个桶按 hash & 8（旧长度）拆成两条，是 0 的留在原下标、否则搬到「原下标 + 8」。lemon 最后放进新表的 2 号桶。整个过程中 get 都不加锁 —— table、节点的 val 和 next 都是 volatile。演示结束。`}]};export{e as default};